#include <iostream>
using namespace std;

int main() {
    int rows = 2, cols = 3;
    int** arr = new int*[rows];
    for (int i = 0; i < rows; i++) {
        arr[i] = new int[cols];
    }
    arr[0][0] = 1; arr[1][2] = 2;
    cout << arr[0][0] << " " << arr[1][2] << endl;
    for (int i = 0; i < rows; i++) delete[] arr[i];
    delete[] arr;
    return 0;
}
